inline int llfsm_check(int value, int lower, int upper, const char *name)
{
    if (value < lower || value > upper) {
        std::cout.flush();
        std::cerr << "range violation " << name << '\n';
        std::exit(2);
    }
    return value;
}

inline std::size_t llfsm_index(int index, int size, const char *name)
{
    return static_cast<std::size_t>(llfsm_check(index, 0, size - 1, name));
}

inline void llfsm_print_bool(bool value)
{
    std::cout << (value ? "true" : "false");
}

inline void llfsm_print_int(int value)
{
    std::cout << value;
}

using Flag = bool;

inline bool llfsm_parse_Flag(const std::string &text, Flag &out)
{
    if (text == "true" || text == "false") {
        out = text == "true";
        return true;
    }
    return false;
}

using Count = int;

inline bool llfsm_parse_Count(const std::string &text, Count &out)
{
    char *end = nullptr;
    errno = 0;
    long value = std::strtol(text.c_str(), &end, 10);
    if (end == text.c_str() || *end != '\0' || errno != 0 || value < 0 || value > 9) {
        return false;
    }
    out = static_cast<int>(value);
    return true;
}

class TallyCounter {
public:
    void bump(Count by)
    {
        total += by;
    }

    Count sum() const
    {
        return total;
    }

private:
    Count total = 0;
};

Flag isEven(Count n)
{
    return n % 2 == 0;
}

void note(Count n)
{
    std::cout << "note " << n << '\n';
}

using Tally = TallyCounter;

Flag isEven(Count n);
void note(Count n);

class llfsm_Arrangement;

enum class Counter_State { Start, Work, Pause, Done };

inline std::string_view llfsm_name(Counter_State state)
{
    constexpr std::array<std::string_view, 4> names{{ "Start", "Work", "Pause", "Done" }};
    return names[static_cast<std::size_t>(state)];
}

inline bool llfsm_is_accepting(Counter_State state)
{
    constexpr std::array<bool, 4> flags{{ false, false, false, true }};
    return flags[static_cast<std::size_t>(state)];
}

inline bool llfsm_is_pass_through(Counter_State state)
{
    constexpr std::array<bool, 4> flags{{ false, false, true, false }};
    return flags[static_cast<std::size_t>(state)];
}

struct Counter_Machine {
    Counter_State llfsm_pc = Counter_State::Start;
    bool llfsm_entered = true;
    Count n{};

    void llfsm_ringlet(llfsm_Arrangement &llfsm_arrangement);
};

class llfsm_Arrangement {
public:
    Tally tally{};
    Counter_Machine llfsm_instance_counter;

    llfsm_Arrangement()
    {
        tally = (TallyCounter{});
        llfsm_instance_counter.n = 0;
    }

    bool llfsm_set_external(const std::string &key, bool indexed, int index, const std::string &value)
    {
        (void)key;
        (void)indexed;
        (void)index;
        (void)value;
        return false;
    }

    bool llfsm_apply_assignment(std::string token)
    {
        std::size_t equals = token.find('=');
        if (equals == std::string::npos) {
            return false;
        }
        std::string value = token.substr(equals + 1);
        token.erase(equals);
        bool indexed = false;
        int index = 0;
        std::size_t bracket = token.find('\x5b');
        if (bracket != std::string::npos) {
            const std::string position = token.substr(bracket + 1);
            std::size_t first = (!position.empty() && (position[0] == '+' || position[0] == '-')) ? 1 : 0;
            if (position.size() < first + 2 || position.back() != '\x5d'
                || position.find_first_not_of("0123456789", first) != position.size() - 1) {
                return false;
            }
            errno = 0;
            long parsed = std::strtol(position.c_str(), nullptr, 10);
            if (errno != 0 || parsed < INT_MIN || parsed > INT_MAX) {
                return false;
            }
            index = static_cast<int>(parsed);
            indexed = true;
            token.erase(bracket);
        }
        return llfsm_set_external(token, indexed, index, value);
    }

    bool llfsm_apply_inputs(const std::vector<std::string> &lines, int round)
    {
        for (const std::string &line : lines) {
            std::istringstream fields(line);
            long when = 0;
            if (!(fields >> when) || when != round) {
                continue;
            }
            std::string token;
            while (fields >> token) {
                if (!llfsm_apply_assignment(token)) {
                    std::cerr << "invalid input " << token << '\n';
                    return false;
                }
            }
        }
        return true;
    }

    int llfsm_run(int maxRounds, const std::vector<std::string> &inputLines)
    {
        std::cout << "arrangement HostTally\n";
        for (int round = 1; ; round++) {
            if (!llfsm_apply_inputs(inputLines, round)) {
                return 1;
            }
            llfsm_instance_counter.llfsm_ringlet(*this);
            std::cout << "R" << round << " counter " << llfsm_name(llfsm_instance_counter.llfsm_pc) << '\n';
            if (llfsm_is_accepting(llfsm_instance_counter.llfsm_pc) && !llfsm_instance_counter.llfsm_entered) {
                std::cout << "halt R" << round << '\n';
                break;
            }
            if (round == maxRounds) {
                break;
            }
        }
        return 0;
    }
};

void Counter_Machine::llfsm_ringlet(llfsm_Arrangement &llfsm_arrangement)
{
    Tally &tally = llfsm_arrangement.tally;
    (void)llfsm_arrangement;
    (void)tally;
    for (;;) {
        if (llfsm_entered) {
            llfsm_entered = false;
            switch (llfsm_pc) {
            case Counter_State::Start:
                std::cout << "start\n";
                break;
            case Counter_State::Work:
                tally.bump(n);
                note(n);
                n = llfsm_check((n + 1), 0, 9, "n");
                std::cout << "sum";
                std::cout << ' ';
                llfsm_print_int(tally.sum());
                std::cout << '\n';
                break;
            case Counter_State::Pause:
                std::cout << "pause";
                std::cout << ' ';
                llfsm_print_int(n);
                std::cout << '\n';
                break;
            case Counter_State::Done:
                std::cout << "done\n";
                break;
            default:
                break;
            }
        }
        bool llfsm_fired = true;
        switch (llfsm_pc) {
        case Counter_State::Start:
            if (true) {
                llfsm_pc = Counter_State::Work;
            } else {
                llfsm_fired = false;
            }
            break;
        case Counter_State::Work:
            if (tally.sum() >= 6) {
                llfsm_pc = Counter_State::Done;
            } else if (isEven(n)) {
                llfsm_pc = Counter_State::Pause;
            } else if (true) {
                llfsm_pc = Counter_State::Work;
            } else {
                llfsm_fired = false;
            }
            break;
        case Counter_State::Pause:
            if (true) {
                llfsm_pc = Counter_State::Work;
            } else {
                llfsm_fired = false;
            }
            break;
        default:
            llfsm_fired = false;
            break;
        }
        if (!llfsm_fired) {
            return;
        }
        llfsm_entered = true;
        if (!llfsm_is_pass_through(llfsm_pc)) {
            return;
        }
    }
}

int main(int argc, char **argv)
{
    int maxRounds = argc > 1 ? std::atoi(argv[1]) : 20;
    std::vector<std::string> inputLines;
    if (argc > 2) {
        std::ifstream inputs(argv[2]);
        if (!inputs) {
            std::cerr << "cannot open " << argv[2] << '\n';
            return 1;
        }
        std::string line;
        while (std::getline(inputs, line)) {
            inputLines.push_back(line);
        }
    }
    llfsm_Arrangement arrangement;
    return arrangement.llfsm_run(maxRounds, inputLines);
}
